AssistantMessageToolRequest(name='create', tool_call_id='function-call-2976ce69-5c20-44aa-8628-22e8f02c5a0d', arguments={'file_text': 'document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('quiz-form');
    const resultsContainer = document.getElementById('results');

    const correctAnswers = {
        q1: ['cpp', 'rust'],
        q2: ['html', 'css', 'js'],
        q3: ['haskell', 'lisp', 'elixir']
    };

    form.addEventListener('submit', (event) => {
        event.preventDefault();

        // Reset errors
        const errorElements = document.querySelectorAll('.error-text');
        errorElements.forEach(el => {
            el.textContent = '';
            el.hidden = true;
        });

        const fieldsets = document.querySelectorAll('fieldset');
        fieldsets.forEach(fs => fs.removeAttribute('aria-invalid'));

        let isValid = true;
        let firstInvalidFieldset = null;

        // Validate: at least one checkbox selected per question
        ['q1', 'q2', 'q3'].forEach(q => {
            const checked = form.querySelectorAll(`input[name="${q}"]:checked`);
            if (checked.length === 0) {
                isValid = false;
                const errorEl = document.getElementById(`${q}-error`);
                errorEl.textContent = 'Error: Please select at least one answer.';
                errorEl.hidden = false;

                const fieldset = document.getElementById(`${q}-group`);
                fieldset.setAttribute('aria-invalid', 'true');
                fieldset.setAttribute('aria-describedby', `${fieldset.getAttribute('aria-describedby') || ''} ${q}-error`.trim());

                if (!firstInvalidFieldset) {
                    firstInvalidFieldset = fieldset.querySelector('input[type="checkbox"]');
                }
            }
        });

        if (!isValid) {
            if (firstInvalidFieldset) {
                firstInvalidFieldset.focus();
            }
            return;
        }

        // Calculate score
        let score = 0;
        const totalQuestions = Object.keys(correctAnswers).length;

        Object.keys(correctAnswers).forEach(q => {
            const checkedValues = Array.from(form.querySelectorAll(`input[name="${q}"]:checked`)).map(cb => cb.value);
            const correctValues = correctAnswers[q];

            // Check if user selected EXACTLY the correct answers
            const isCorrect = checkedValues.length === correctValues.length && 
                              checkedValues.every(val => correctValues.includes(val));

            if (isCorrect) {
                score++;
            }
        });

        // Display results
        resultsContainer.textContent = `You scored ${score} out of ${totalQuestions}!`;
        resultsContainer.className = 'results-container visible ' + (score === totalQuestions ? 'results-success' : 'results-error');

        // Ensure the status message is perceived
        // resultsContainer.focus() is NOT recommended for role="status", but if we want to ensure they see it, we can scroll or just let AT handle it.
        // Actually, for a quiz result, scrolling to it or moving focus might be helpful if it's far down.
        resultsContainer.scrollIntoView({ behavior: 'smooth' });
    });
});
