:root {
    --primary-color: #0066cc;
    --primary-hover: #0052a3;
    --bg-color: #f8f9fa;
    --text-color: #212529;
    --border-color: #dee2e6;
    --error-color: #dc3545;
    --help-text-color: #6c757d;
    --white: #ffffff;
    --shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    --border-radius: 8px;
}

* {
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    line-height: 1.6;
    color: var(--text-color);
    background-color: var(--bg-color);
    margin: 0;
    padding: 2rem 1rem;
    display: flex;
    flex-direction: column;
    align-items: center;
}

header {
    margin-bottom: 2rem;
    text-align: center;
}

h1 {
    font-size: 2rem;
    font-weight: 700;
    color: var(--primary-color);
}

.required-note {
    font-size: 0.9rem;
    color: var(--help-text-color);
    margin-bottom: 1.5rem;
}

main {
    width: 100%;
    max-width: 600px;
    background: var(--white);
    padding: 2rem;
    border-radius: var(--border-radius);
    box-shadow: var(--shadow);
}

.form-field {
    margin-bottom: 2rem;
}

fieldset {
    border: 1px solid var(--border-color);
    border-radius: var(--border-radius);
    padding: 1.5rem;
    margin: 0;
}

legend {
    font-weight: 600;
    font-size: 1.1rem;
    padding: 0 0.5rem;
}

.help-text {
    font-size: 0.9rem;
    color: var(--help-text-color);
    margin: 0.5rem 0 1rem 0;
}

.option {
    display: flex;
    align-items: flex-start;
    margin-bottom: 0.75rem;
    padding: 0.5rem;
    border-radius: 4px;
    transition: background-color 0.2s;
}

.option:hover {
    background-color: #f1f3f5;
}

input[type="checkbox"] {
    width: 1.2rem;
    height: 1.2rem;
    margin-right: 0.75rem;
    margin-top: 0.2rem;
    cursor: pointer;
}

label {
    cursor: pointer;
    flex: 1;
}

.error-text {
    color: var(--error-color);
    font-size: 0.9rem;
    margin-top: 0.5rem;
    font-weight: 500;
}

.form-actions {
    margin-top: 2rem;
    display: flex;
    justify-content: flex-end;
}

button {
    background-color: var(--primary-color);
    color: var(--white);
    border: none;
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    font-weight: 600;
    border-radius: var(--border-radius);
    cursor: pointer;
    transition: background-color 0.2s, transform 0.1s;
}

button:hover {
    background-color: var(--primary-hover);
}

button:active {
    transform: translateY(1px);
}

button:focus-visible {
    outline: 3px solid rgba(0, 102, 204, 0.4);
    outline-offset: 2px;
}

.results-container {
    margin-top: 2rem;
    padding: 1.5rem;
    border-radius: var(--border-radius);
    display: none;
}

.results-container.visible {
    display: block;
}

.results-success {
    background-color: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

.results-error {
    background-color: #f8d7da;
    color: #721c24;
    border: 1px solid #f5c6cb;
}

/* Accessibility: Ensure focus is visible on checkboxes */
input[type="checkbox"]:focus-visible + label {
    outline: 2px solid var(--primary-color);
    outline-offset: 4px;
    border-radius: 2px;
}

@media (max-width: 480px) {
    main {
        padding: 1rem;
    }

    fieldset {
        padding: 1rem;
    }
}
